export function maxmemoryPolicyToUi(apiValue: string): string {
  const hyphenated = apiValue.replace(/_/g, "-");
  return (MAXMEMORY_POLICIES as readonly string[]).includes(hyphenated)
    ? hyphenated
    : apiValue;
}

